export function conversationMarkup(en: boolean, registration: boolean, signInUrl: string, signUpUrl: string): string {
 const tr = (pl: string, english: string) => en ? english : pl
 const icon = (path: string) => `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${path}"/></svg>`
 const avatar = `<span class="sg-v2-avatar"><img data-avatar src="${conversationAssets.female}" alt="" referrerpolicy="no-referrer"></span>`
 return `<header class="sg-v2-page-header"><span class="sg-v2-logo-stage">${spendGuruLogo}</span><div class="sg-v2-header-actions"><small class="sg-v2-context">${registration ? tr('Rejestracja','Registration') : tr('Logowanie','Sign in')} · SpendGuru</small><a class="sg-v2-text-button" href="${registration ? signInUrl : signUpUrl}">${registration ? tr('Mam już konto','I have an account') : tr('Utwórz konto','Create an account')}</a><button id="logout" class="sg-v2-text-button" hidden>${tr('Wyloguj się','Sign out')}</button></div></header>
 <main class="sg-v2-layout" id="chat-interface"><aside class="sg-v2-story"><span class="sg-v2-eyebrow">${registration ? tr('MIŁO CIĘ POZNAĆ','NICE TO MEET YOU') : tr('DOBRZE, ŻE JESTEŚ','GOOD TO SEE YOU')}</span><h1>${registration ? tr('Twoje konto.<br>Zacznijmy od<br>rozmowy.','Your account.<br>Let’s start with<br>a conversation.') : tr('Dobrze Cię<br>znów widzieć.','Good to see<br>you again.')}</h1><p class="sg-v2-intro">${tr('W Twoim tempie. Po jednej odpowiedzi, krok po kroku.','At your pace. One answer at a time, step by step.')}</p><div class="sg-v2-progress">${[tr('Twój rozmówca','Your guide'),registration ? tr('Podstawowe dane','Your details') : tr('Sposób logowania','Sign-in method'),tr('Potwierdzenie e-maila','Email verification')].map((x,i)=>`<div data-step class="sg-v2-step ${i===0?'is-current':'is-muted'}"><span class="sg-v2-step-index">0${i+1}</span>${x}</div>`).join('')}</div></aside>
 <section class="sg-v2-chat" aria-label="${tr('Rozmowa ze SpendGuru','Conversation with SpendGuru')}"><div class="sg-v2-chat-header"><div class="sg-v2-identity">${avatar}<div><b>SpendGuru</b><p id="chat-status" class="sg-v2-status">${tr('Jeszcze chwila…','One moment…')}</p></div></div><div class="sg-v2-actions"><button type="button" id="avatar-switch" aria-label="${tr('Zmień awatara','Change avatar')}" title="${tr('Zmień awatara','Change avatar')}">${icon('M4 7h15m-4-4 4 4-4 4M20 17H5m4-4-4 4 4 4')}</button><button type="button" id="restart" aria-label="${tr('Od początku','Start again')}" title="${tr('Od początku','Start again')}">${icon('M3 10a9 9 0 1 1 1.8 8M3 4v6h6M12 7v5l3 2')}</button></div></div>
 <div class="sg-v2-history" id="history" role="log" aria-live="polite" aria-relevant="additions"><p class="sg-v2-divider">${registration ? tr('POZNAJMY SIĘ','LET’S GET ACQUAINTED') : tr('WRACAMY DO ROZMOWY','LET’S CONTINUE')}</p><div id="typing" class="sg-v2-typing" hidden>${avatar}<div class="sg-v2-dots-bubble" aria-label="${tr('SpendGuru pisze','SpendGuru is typing')}"><span class="sg-v2-dot"></span><span class="sg-v2-dot"></span><span class="sg-v2-dot"></span></div></div><div id="sign-in"></div></div><div id="choices" class="sg-v2-choices"></div>
 <div class="sg-v2-composer"><p id="chat-error" class="sg-v2-error" role="alert"></p><form id="composer-form" hidden><div class="sg-v2-input-wrap"><input id="answer" class="sg-v2-input" aria-label="${tr('Odpowiedź','Your answer')}" maxlength="320"><div id="otp" class="sg-v2-otp" hidden>${Array.from({length:6},(_,i)=>`<input class="sg-v2-code-input" type="text" inputmode="numeric" autocomplete="${i===0?'one-time-code':'off'}" maxlength="6" aria-label="${tr('Cyfra','Digit')} ${i+1}">`).join('')}</div></div><button id="send" class="sg-v2-send" type="submit" aria-label="${tr('Wyślij','Send')}" title="${tr('Wyślij','Send')}">${icon('m5 12 7-7 7 7M12 5v14')}</button></form><div class="sg-v2-links"><button id="resend" type="button" hidden>${tr('Wyślij kod ponownie','Send a new code')}</button><button id="switch-method" type="button" hidden>${tr('Zmień metodę','Change method')}</button></div><div id="clerk-captcha"></div><button id="retry" type="button" class="sg-v2-text-button" hidden>${tr('Spróbuj ponownie','Try again')}</button></div></section></main><p id="status" class="sg-v2-status-line" role="status">${tr('Sprawdzamy Twoją sesję…','Checking your session…')}</p><footer class="sg-v2-footer"><span>SpendGuru / Profitia</span><span>${tr('Bezpieczne logowanie z Clerk','Secure sign-in with Clerk')}</span></footer>`
}
